def count():
    total = 0
    offset = 0
    while True:
        r = query_logs(service='worker', level='WARN', limit=500, offset=offset)
        items = r['items']
        for it in items:
            if 'cache' in it['msg'].lower():
                total += 1
        if len(items) < 500:
            break
        offset += 500
    return total

